import store from '@/store/index.js'
import check from './check.js'
export default {
	post(data, func) {
		window[data.callback] = func

		if (check.isIOS() && window.webkit) {
			data.param = JSON.stringify(data.param)
			window.webkit.messageHandlers.SDKBridge.postMessage(data)
		} else {
			let methodName = data.method
			window.SDKBridge = window.SDKBridge ? window.SDKBridge : {}
			if (window.SDKBridge[methodName]) {
				window.SDKBridge[methodName](JSON.stringify(data))
			}
		}
	},
	loadFunc() {
		this.post({
			method: 'getHeader',
			param: {},
			callback: 'getHeader',
		}, (code, data) => {
			store.commit('SET_INITDATA', data)
			//console.log('bridge =>' + code)
			//console.log(data)
		})
	},
	postLoginSuccess(key, param) {
		//loginSuccess registeredSuccess loginFailed registeredFailed
		this.post({
			method: key,
			param: param,
			callback: key,
		}, (code, data) => {
			console.log('postLoginSuccess=>', code, data)
		})
	},
	postLogin(key) {
		//appleLogin facebookLogin 
		return new Promise((rev, rej) => {
			this.post({
				method: key,
				param: {},
				callback: key,
			}, (code, data) => {
				//console.log('postLogin=>', code, data)
				if (code != 0) {
					return rej(code)
				}
				return rev(data)
			})
		})
	},
	closeWebView(param) {
		this.post({
			method: 'closeWebView',
			param: param,
			callback: 'closeWebView',
		}, (code, data) => {
			console.log('closeWebView:', code, data)
		})
	},
	bindSuccess(param) {
		return new Promise((rev, rej) => {
			this.post({
				method: 'bindSuccess',
				param: param,
				callback: 'bindSuccess',
			}, (code, data) => {
				if (code != 0) {
					return rej(code)
				}
				return rev(data)
			})
		})
	},
	logout(param) {
		this.post({
			method: 'logout',
			param: param,
			callback: 'logout',
		}, (code, data) => {
			console.log('logout:', code, data)
		})
	},
	getPasteData() {
		return new Promise((rev, rej) => {
			this.post({
				method: 'getPasteData',
				param: {},
				callback: 'getPasteData',
			}, (code, data) => {
				console.log(arguments)
				if (code != 0) {
					return rej(code)
				}
				return rev(data)
			})
		})
	}
}
