import {
	createStore
} from 'vuex'
import login from './modules/loginStore.js'
import register from './modules/registerStore.js'
import bind from './modules/bindStore.js'
import auth from './modules/authStore.js'
import service from './modules/serviceStore.js'
import updatePassword from './modules/updatePasswordStore.js'

import logoff from './modules/logoffStore.js'

import createPersistedState from 'vuex-persistedstate'

const store = createStore({
	plugins: [createPersistedState({
		key: 'stort' //localStorage名为stort
	})],
	state() {
		return {
			initData: null,
			userInfo: null,
			orientation: window.orientation,
			keepAliveList: [],
			loginRemember: null,
			showVerify:false,
			captchaVerification:null,
			lastRequestConfig:null,
			loginWithoutAccountLocal:true,//默认打开  即首次打开即可游客登录
		}
	},
	mutations: {
		SET_INITDATA(state, data) {
			state.initData = data
		},
		SET_USER_INFO(state, data) {
			state.userInfo = data
		},
		SET_ORIENTATION(state, data) {
			state.orientation = data
		},
		SET_KEEP_ALIVE_LIST(state, data) {
			state.keepAliveList = data
		},
		PUSH_KEEP_ALIVE_LIST(state, data) {
			state.keepAliveList.push(data)
		},
		DELETE_KEEP_ALIVE_LIST(state, data) {
			let index = state.keepAliveList.findIndex(item => item.subject == data)
			if (index >= 0) {
				state.keepAliveList.splice(index, 1)
			}
		},
		SET_LOGIN_REMBER(state, data) {
			state.loginRemember = data
		},
		SET_SHOW_VERIFY(state, data) {
			state.showVerify = data
		},
		SET_CAPTCHA_VERIFICATION(state, data) {
			state.captchaVerification = data
			state.showVerify = false
		}, 
		SET_LAST_REQUEST_CONFIG(state,data){
			state.lastRequestConfig = data
		},
		SET_LOGIN_WITHOUT_ACCOUNT_LOCAL(state,data){
			state.loginWithoutAccountLocal = data
		}
	},
	getters: {
		initData(state) {
			return state.initData
		},
		userInfo(state) {
			return state.userInfo
		},
		orientation(state) {
			if (state.orientation == 180 || state.orientation == 0) {
				return 0
			}
			if (state.orientation == 90 || state.orientation == -90) {
				//横屏
				return 1
			}
			return 0
		},
		loginRemember(state) {
			return state.loginRemember
		},
		keepAliveList(state) {
			return state.keepAliveList
		},
		LoginTypeDic() { //登录类型字典
			return {
				guestLogin: 0,
				phoneLogin: 1,
				wxLogin: 2,
				qqLogin: 3,
				wbLogin: 4,
				appleLogin: 5,
				facebookLogin: 6,
				taptapLogin: 7,
				emailLogin: 8,
				tokenLogin: 9,
			}
		},
		showVerify(state) {
			return state.showVerify
		},
		captchaVerification(state) {
			return state.captchaVerification
		},
		lastRequestConfig(state){
			return state.lastRequestConfig
		},
		loginWithoutAccountLocal(state){
			return state.loginWithoutAccountLocal
		},
	},
	actions: {},
	modules: {
		login,
		register,
		bind,
		auth,
		service,
		updatePassword,
		logoff
	}
});
window.addEventListener('orientationchange', () => {
	store.commit('SET_ORIENTATION', window.orientation)
});
export default store;
