import api from '@/store/api.js'
import check from '@/assets/js/check.js'
//import toast from '@/components/plugs/toast/index.js'

const state = {
	useName: "register",
}
const mutations = {

}
const getters = {

}
const actions = {
	async register(store, data) {

		if (data.phone[0] != '+') {
			data.phone = '+86' + data.phone
		}
		data.password = check.passwordFilter(data.password) 
		return await api.post('player/register', data)
	},
	async getCode(store, data) {
		//TYPE:类型 1注册 2忘记密码 3换绑手机 4老手机号验证

		if (data.phone[0] != '+') {
			data.phone = '+86' + data.phone
		}
		return await api.post('sms/send', data)
	},
	async forget(store, data) {

		if (data.phone[0] != '+') {
			data.phone = '+86' + data.phone
		}
		data.password =  check.passwordFilter(data.password) 
		return await api.post('player/retrievePass', data)
	},
}

export default {
	namespaced: true,
	state,
	mutations,
	getters,
	actions
}
