<template>
	<div class="confirm" v-show="showConfrim">
		<div class="confirm-box" @click.stop="">

			<div class="body">

				<p v-html="text"></p>
				<br/>
				<div class="bg-lightgrey border-radius-10 padding-10 text-left cell">
					<div class="input">
						<input v-model="confirmInput" placeholder="我确认注销账号及其下所有角色" name="name" type="text" />
						
					</div>
				</div>

			</div>
			<div class="foot">

				<div class="cancel btn border-red font-color-red" @click="cancel()" v-show="showCancel">{{cancelText}}
				</div>&nbsp;
				<div class="submit btn bg-red btn-primary color-white" @click="submit()">{{submitText}}</div>

			</div>
		</div>
	</div>
</template>

<script>
	export default {
		name: "confirmHesitate",
		data() {
			return {
				text: '确定',
				title: '提示',
				submitCallBack: () => {},
				submitText: '确 定',
				cancelCallBack: () => {},
				cancelText: '取 消',
				showConfrim: false,
				showCancel: true,
				confirmInput:'',
				confirmVerify:()=>{}
			};
		},
		methods: {
			show(option) {
				Object.assign(this, option)
				this.showConfrim = true
				document.body.appendChild(this.$el)
				// this.text = text
				// this.submitCallBack = submitCallBack ? submitCallBack : () => {}
				// this.submitText = submitText ? submitText : '确 定'
				// this.cancelCallBack = cancelCallBack ? cancelCallBack : () => {}
				// this.cancelText = cancelText ? cancelText : '取 消'
			},
			close() {
				this.confirmInput = ''
				this.text = '确定'
				this.title = '提示'
				this.submitCallBack = () => {}
				this.cancelCallBack = () => {}
				this.confirmVerify = () => {}
				this.submitText = '确 定'
				this.cancelText = '取 消'
				this.showConfrim = false
				this.showCancel = true
				document.body.removeChild(this.$el)
			},
			cancel() {
				this.cancelCallBack()
				this.close()
			},
			submit() {
				if(this.confirmInput!='我确认注销账号及其下所有角色'){
					return this.confirmVerify()
				}
				this.submitCallBack()
				this.close()
			}
		}
	}
</script>

<style scoped>
	input ,.input{
		background: none;
		outline: none;
		border: none;
		width: 100%;
	}

	.confirm {
		height: 100vh;
		width: 100vw;
		position: absolute;
		top: 0;
		left: 0;
		background-color: rgba(0, 0, 0, 0.6);
		display: flex;
		align-items: center;
		justify-content: center;
		text-align: center;
	}

	.confirm-box {

		border-radius: 6px;
		width: 80%;
		max-height: 90vh;
		margin: 0 auto;
		overflow: hidden;
	}

	.body {
		background-color: #ffffff;
		padding: 30px;
		color: #686e3f;
		max-height: 40vh;
		overflow-y: scroll;
		padding-bottom: 0;
		text-align: left;
	}

	.foot {
		background-color: #ffffff;
		color: #686e3f;
		padding: 16px;
	}

	.submit {
		width: 40%;
		display: inline-block;
		color: white;
		border-radius: 50px;
		margin: 0 auto;
		padding: 6px;
	}

	.cancel {
		width: 40%;
		display: inline-block;
		border-radius: 50px;
		margin: 0 auto;
		padding: 6px;
	}
</style>
