import {
	createApp
} from "vue"
import Component from './index.vue'
export default {
	component: null,
	install(Vue) {
		if (this.component) {
			// 防止多次载入
			Vue.config.globalProperties['$'+Component.name] = this.component;
			return;
		}
		let instance = createApp(Component);
		let parent = document.createElement("div")
		let bodyDom = document.body
		// 这里需要注意，大概率app还没有mount，导致获取不到app节点，所以想挂载到app上，需要保证app已经创建。
		bodyDom.appendChild(parent)
		this.component = instance.mount(parent)

		Vue.config.globalProperties['$'+Component.name] = this.component;
	}
};
