<template>
	<router-view v-slot="{ Component }">
		<keep-alive :include="keepAliveList">
			<component :is="Component"></component>
		</keep-alive>
	</router-view>


	<div>{{text}}</div>
	<Verify mode="pop" @handleSuccess="handleSuccess" :captchaType="captchaType"
		:imgSize="{width:'300px',height:'200px'}" ref="verify"></Verify>
</template>

<script>
	import {
		ref
	} from 'vue'
	import VERSION_MAP_IOS from '@/assets/js/version-ios.js'
	import VERSION_MAP_ANDROID from '@/assets/js/version-android.js'
	import Verify from '@/components/plugs/verifition/Verify'

	import axios from "axios"
	export default {
		name: 'App',
		components: {
			Verify
		},
		setup() {


			const verify = ref(null)
			const captchaType = ref('')
			const onShow = (type) => {
				captchaType.value = type
				verify.value.show()
			}
			const handleSuccess = (res) => {
				console.log(res);
				console.log('SET_SHOW_VERIFY  sucess');

				this.$store.commit('SET_SHOW_VERIFY', false)
			}
			return {
				verify,
				handleSuccess,
				onShow,
				captchaType
			}
		},
		data() {
			return {
				text: ''
			}
		},
		async created() {

			if (this.initData && this.initData.yofiSdkVersion) {
				console.log("process.env.VUE_APP_VERSION |=====> " + process.env.VUE_APP_VERSION)
				console.log("yofiSdkVersion |=====> " + this.initData.yofiSdkVersion)
				const VERSION_MAP = this.$check.isIOS() ? VERSION_MAP_IOS : VERSION_MAP_ANDROID
				let target = VERSION_MAP[this.initData.yofiSdkVersion] || process.env.VUE_APP_VERSION

				console.log("target |=====> " + target)
				if (target != process.env.VUE_APP_VERSION) {
					let href = window.location.href.split('#')
					console.log("href |=====> " + href)
					if (href.length == 2) {
						console.log("location.href |=====> " + (href[0] + 'index-' + target + '.html' + '#' + href[1]))

						try {
							let res = await axios.get(href[0] + 'index-' + target + '.html' + '#' + href[1])
							window.location.href = href[0] + 'index-' + target + '.html' + '#' + href[1]
							console.log(res.data)
						} catch (e) {
							console.log('跳转失败=====>' + e)
						}



					}
				}
			}
			//解决登录框不下来问题
			let i = window.innerHeight
			window.addEventListener('resize', () => {
				let n = window.innerHeight
				if (i <= n) {
					this.text = '强制更新'
					setTimeout(() => {
						this.text = ''
					}, 10)
				}

			})
		},
		computed: {
			keepAliveList() {
				return this.$store.getters.keepAliveList
			},
			showVerify() {
				return this.$store.getters.showVerify
			}
		},
		watch: {
			$route(to, from) {
				if (to.meta.keepAlive && this.keepAliveList && this.keepAliveList.indexOf(to.name) === -1) {
					this.$store.commit('PUSH_KEEP_ALIVE_LIST', to.name)
				}
				if (from.name == 'Login' && (to.name == 'Switch' || to.name == '/')) {
					this.$bridge.closeWebView()

				}
			},
			showVerify(cv) {
				if (cv) {
					this.onShow('blockPuzzle')
				}
			}
		},
	}
</script>

<style>
	#app {
		overflow-y: scroll;
	}
</style>
