import api from '@/store/api.js'
import check from '@/assets/js/check.js'
const state = {
	useName: "updatePassword",
}
const mutations = {

}
const getters = {

}
const actions = {
	async updatePass(store, data) {
		data.newPassword = check.passwordFilter(data.newPassword)
		data.oldPassword = check.passwordFilter(data.oldPassword)
		return await api.post('playerCenter/updatePass', data)
	},
}

export default {
	namespaced: true,
	state,
	mutations,
	getters,
	actions
}
