export default {
	data() {
		return {
			passwordPlaceHolder: '任意6~20位数字/字母/下划线组合',
		}
	},
	computed: {
		ios13() {
			return this.$check.ios13()
		},
		isIOS() {
			return this.$check.isIOS()
		},
		userInfo() {
			return this.$store.getters['userInfo']
		},
		initData() {
			return this.$store.getters.initData
		},
		LoginTypeDic() {
			return this.$store.getters['LoginTypeDic']
		},

	},
	watch: {
		username(cv) {
			if (cv != '' && this.$check.isSpecialString(cv)) {
				this.username = cv.substr(0, cv.length - 1)
				return this.$toast.show('手机号不能是特殊字符')
			}
			if (cv != '' && isNaN(cv[cv.length - 1])) {
				this.username = cv.substr(0, cv.length - 1)
				return this.$toast.show('手机号必须是数字')
			}
			if (cv != '' && cv.length > 11) {
				this.username = cv.substr(0, cv.length - 1)
				return this.$toast.show('手机号不能超过11位')
			}
		},
		idCard(cv) {
			if (cv != '' && this.$check.isSpecialString(cv)) {
				this.idCard = cv.substr(0, cv.length - 1)
				return this.$toast.show('身份证不能是特殊字符')
			}
			if (cv && cv[cv.length - 1].match(/^[\u4e00-\u9fa5]+$/)) {
				this.idCard = cv.substr(0, cv.length - 1)
				return this.$toast.show('身份证不能是中文')
			}
		},
		password(cv) {
			if(this.$route.name=='Login'){
				return
			}
			if (cv != '' && this.$check.isSpecialString(cv)) {
				this.password = cv.substr(0, cv.length - 1)
				return this.$toast.show('密码不能是特殊字符')
			}
			if (cv != '' && cv.length > 20) {
				this.password = cv.substr(0, cv.length - 1)
				return this.$toast.show('密码长度需大于6位小于20位')
			}
			if (cv && cv[cv.length - 1].match(/^[\u4e00-\u9fa5]+$/)) {
				this.password = cv.substr(0, cv.length - 1)
				return this.$toast.show('密码不能是中文')
			}
		},
		// repeatPassword(cv) {
		// 	if (cv.length > 20) {
		// 		this.repeatPassword = cv.substr(0, cv.length - 1)
		// 		if (this.value != '') {
		// 			this.value = this.value.substr(0, this.value.length - 1)
		// 		}
		// 		return this.$toast.show('重复密码长度需大于6位小于20位')
		// 	}
		// },
		code(cv) {
			if (cv != '' && isNaN(cv)) {
				this.code = cv.substr(0, cv.length - 1)
				return this.$toast.show('请输入正确验证码')
			}
		},
		oldPassword() {
			this.passwordVurify('oldPassword', '旧密码')
		},
		newPassword() {
			this.passwordVurify('newPassword', '新密码')
		},
		repeatPassword() {
			this.passwordVurify('repeatPassword', '重复密码')
		},
	},
	methods: {
		passwordVurify(key, type) {
			if (this.$check.isSpecialString(this[key]) && this[key] != "") {
				this[key] = this[key].substr(0, this[key].length - 1)
				return this.$toast.show(type + '不能是特殊字符')
			}
			if (this[key].length > 20) {
				this[key] = this[key].substr(0, this[key].length - 1)
				return this.$toast.show(type + '长度需大于6位小于20位')
			}
			let cv = this[key]
			if (cv && cv[cv.length - 1].match(/^[\u4e00-\u9fa5]+$/)) {
				this[key] = this[key].substr(0, this[key].length - 1)
				return this.$toast.show('密码不能是中文')
			}
		},
		clickCheck() {
			if (!this.loading) {
				this.checked = !this.checked
			}
		},
		inputFocus() {
			const focus = document.getElementsByClassName('input-focus')
			for (let i = 0; i < focus.length; i++) {
				focus[i].addEventListener('mousedown', (e) => {
					e.preventDefault()
				})
			}
		},
		clearInput(key) {
			this[key] = ''
			const likeArray = document.getElementsByClassName('input-focus')
			Array.from(likeArray, input => input.focus())
		},
		go(route) {
			if (route == 'back') {
				this.$router.back()
			} else {
				this.$router.push(route)
			}
		},
		focusin(e) {
			if (e.target.name != 'name') {
				let self = this
				this.$keybord.show({
					btnText: "确认",
					value: this[e.target.name],
					type: e.target.type,
					name: e.target.name,
					placeholder: e.target.placeholder,
					async inputChange(input) {
						self[e.target.name] = input
						return new Promise((rev) => {
							setImmediate(() => {
								rev(self[e.target.name])
							})
						})

					},
				})
			}
			this.in = true
			setTimeout(() => {
				this.in = false
			}, 10)
		},
		focusout() {
			setTimeout(() => {
				if (!this.in) {
					window.scrollTo(0, 0)
				}
			}, 5)
		}
	},

	directives: {
		focus: {
			mounted: function(el) {
				el.focus() // 页面加载完成之后自动让输入框获取到焦点的小功能
			}
		},
	},

}
