<template>
	<div class="confirm" v-show="showConfrim" @click.stop="close()">
		<div class="confirm-box" @click.stop="">
			<div class="title">

				<img v-show="titleImg" class="title" :src="titleImg" />
				<h2 v-show="!titleImg">{{title}}</h2>
			</div>
			<div class="body">
				<p v-html="text"></p>
			</div>
			<div class="foot">

				<div class="cancel btn border-red font-color-red" @click="cancel()" v-show="showCancel">{{cancelText}}
				</div>&nbsp;
				<div class="submit btn bg-red btn-primary color-white" @click="submit()">{{submitText}}</div>

			</div>
		</div>
	</div>
</template>

<script>
	export default {
		name: "confirm",
		data() {
			return {
				text: '确定',
				titleImg: null,
				title: '提示',
				submitCallBack: () => {},
				submitText: '确 定',
				cancelCallBack: () => {},
				cancelText: '取 消',
				showConfrim: false,
				showCancel: true
			};
		},
		methods: {
			show(option) {
				Object.assign(this, option)
				this.showConfrim = true
				document.body.appendChild(this.$el)
				// this.titleImg = titleImg
				// this.text = text
				// this.submitCallBack = submitCallBack ? submitCallBack : () => {}
				// this.submitText = submitText ? submitText : '确 定'
				// this.cancelCallBack = cancelCallBack ? cancelCallBack : () => {}
				// this.cancelText = cancelText ? cancelText : '取 消'
			},
			close() {
				this.text = '确定'
				this.titleImg = null
				this.title = '提示'
				this.submitCallBack = () => {}
				this.cancelCallBack = () => {}
				this.submitText = '确 定'
				this.cancelText = '取 消'
				this.showConfrim = false
				this.showCancel = true
				document.body.removeChild(this.$el)
			},
			cancel() {
				this.cancelCallBack()
				this.close()
			},
			submit() {
				this.submitCallBack()
				this.close()
			}
		}
	}
</script>

<style scoped>
	input {
		background: none;
		outline: none;
		border: none;
		width: 100%;
	}

	.confirm {
		height: 100vh;
		width: 100vw;
		position: absolute;
		top: 0;
		left: 0;
		background-color: rgba(0, 0, 0, 0.6);
		display: flex;
		align-items: center;
		justify-content: center;
		text-align: center;
	}

	.confirm-box {

		border-radius: 6px;
		width: 80%;
		max-height: 90vh;
		margin: 0 auto;
		overflow: hidden;
	}

	.title {
		background-color: #ffffff;
		color: #686e3f;
		padding: 12px;
		height: 30px;
	}

	.decorate {
		width: 20%;
	}

	.logo {
		width: 140px;
	}

	.close-btn {
		width: 20px;
		float: right;
	}

	.body {
		background-color: #ffffff;
		padding: 20px;
		color: #686e3f;
		max-height: 40vh;
		overflow-y: scroll;
	}


	.foot {
		background-color: #ffffff;
		color: #686e3f;
		padding: 16px;
	}

	.submit {
		width: 40%;
		display: inline-block;
		color: white;
		border-radius: 50px;
		margin: 0 auto;
		padding: 6px;
	}

	.cancel {
		width: 40%;
		display: inline-block;
		border-radius: 50px;
		margin: 0 auto;
		padding: 6px;
	}
</style>
