import api from '@/store/api.js'
import check from '@/assets/js/check.js'
const state = {
	useName: "bind",
}
const mutations = {

}
const getters = {

}
const actions = {
	async verifyOldPhone(store, data) {
		return await api.post('playerCenter/verifyOldPhone', data)
	},
	async updatePhone(store, data) {
		if (data.phone[0] != '+') {
			data.phone = '+86' + data.phone
		}
		data.password = check.passwordFilter(data.password) 
		return await api.post('playerCenter/updatePhone', data)
	},
}

export default {
	namespaced: true,
	state,
	mutations,
	getters,
	actions
}
