import {
	createApp
} from 'vue'
import App from './App.vue'
import router from './router'
import store from './store'
import '@/assets/css/common.css'
import 'lib-flexible'
import bridge from '@/assets/js/bridge'
import check from '@/assets/js/check'
import baseMixin from '@/assets/js/baseMixin'

import toast from '@/components/plugs/toast/index.js'
import confirm from '@/components/plugs/confirm/index.js'
import confirmHesitate from '@/components/plugs/confirmHesitate/index.js'
import keybord from '@/components/plugs/keybord/index.js'

const app = createApp(App)

bridge.loadFunc()
app.mixin(baseMixin)
app.config.globalProperties.$check = check

app.config.globalProperties.$bridge = bridge
app.use(store).use(router).use(toast).use(confirm).use(confirmHesitate).use(keybord).mount('#app')
