import axios from 'axios'
import store from '@/store'
import md5 from 'md5'
import toast from '@/components/plugs/toast/index.js'
import confirm from '@/components/plugs/confirm/index.js'
import Vconsole from 'vconsole'
let BASE_URL = process.env.VUE_APP_BASE_URL

// import check from '@/assets/js/check.js'
process.env.VUE_APP_CONSOLE ? new Vconsole() : ''

let instance = axios.create({
	headers: {
		'Content-Type': 'application/x-www-form-urlencoded'
	}
})
instance.interceptors.request.use(
	config => {
		toast.component.show({
			duration: 3000,
			loading: true
		})

		if (store.getters.initData) {
			config.headers['Content-Type'] = 'application/x-www-form-urlencoded',
				config.headers.clientId = store.getters.initData.clientId
			config.headers.accessToken = store.getters.userInfo ? store.getters.userInfo.accessToken : ''
			// if(check.isIOS()){
			// 	config.headers.yofiDeviceUUID = store.getters.initData.yofiDeviceUUID
			// }

			config.headers.yofiSystem = store.getters.initData.yofiSystem
			config.headers.yofiSdkVersion = store.getters.initData.yofiSdkVersion
			config.headers.yofiVersion = store.getters.initData.yofiVersion
			config.headers.yofiDeviceId = store.getters.initData.yofiDeviceId
			config.headers.yofiChannelId = store.getters.initData.yofiChannelId
			config.headers.yofiPackageName = store.getters.initData.yofiPackageName
			let result = store.getters.initData.appKey
			if (config.data) {
				for (let key of config.data.keys()) {
					result = result + key + config.data.get(key)
				}
				result = result + store.getters.initData.appKey
				config.data.set('sign', md5(result).toLowerCase())
			}

		}

		return config
	},
	err => {
		return Promise.reject([null, err])
	}
)

// http response 拦截器
instance.interceptors.response.use(
	res => {
		if (res.data.code == 909 && res.data.msg) {

			confirm.component.show({
				title: '友情提示',
				text: res.data.msg
			})
			toast.component.hide()
			return res
		}
		if (res.data.code != 0 && res.data.msg) {

			store.commit("SET_CAPTCHA_VERIFICATION", null)
			toast.component.show(res.data.msg)
			return res
		}
		return res

	},
	//接口错误状态处理，也就是说无响应时的处理
	err => {
		toast.component.show(err.response.data)
		return Promise.reject(err.response) // 返回接口返回的错误信息
	}
)

export default {
	TIMER: null,
	BASE_URL: BASE_URL,
	post(path, data, revice) {
		let tempData = Object.assign({}, data)
		let formData = new FormData()
		if (store.getters.initData) {
			if (store.getters.captchaVerification) {
				data.captchaVerification = store.getters.captchaVerification
				store.commit("SET_CAPTCHA_VERIFICATION", null)
			}
			data = Object.assign({
				timestamp: Date.now(),
				channelId: store.getters.initData.yofiChannelId,
				version: store.getters.initData.yofiVersion,
				packageName: store.getters.initData.yofiPackageName,
				realDeviceId: store.getters.initData.yofiDeviceId,
				deviceId: store.getters.initData.yofiDeviceUUID,
				system: store.getters.initData.yofiSystem,
				accessToken: store.getters.userInfo ? store.getters.userInfo.accessToken : '',
			}, data)
		}
		Object.keys(data).sort().forEach(key => {
			if (key == 'password' && data[key].length < 20) {
				formData.append(key, md5(data[key]).toUpperCase())
			} else {
				formData.append(key, data[key])
			}
		})

		return new Promise((rev, rej) => {
			instance.post(BASE_URL + path, formData).then(res => {
				if (res.data.code == 20) {
					store.commit("SET_SHOW_VERIFY", true)
					clearInterval(this.TIMER)
					toast.component.hide()
					this.TIMER = setInterval(async () => {
						if (store.getters.captchaVerification) {
							clearInterval(this.TIMER)

							await this.post(path, tempData, rev)
						}
					}, 200)
				} else {

					store.commit("SET_CAPTCHA_VERIFICATION", null)
					rev = revice || rev
					rev([res])
				}

			}).catch((e) => {
				//toast.component.show(JSON.stringify(e))
				rej([null, e])
			})
		})
	},
	get(path, data) {
		return new Promise((rev, rej) => {
			instance.get(BASE_URL + path, data).then(res => {
				rev([res, null])
			}).catch((e) => {
				//toast.component.show(JSON.stringify(e))
				rej([null, e])
			})
		})
	},

}
