import api from '@/store/api.js'
import check from '@/assets/js/check.js'
//import toast from '@/components/plugs/toast/index.js'

const state = {
	useName: "login",
	userHistory: [],
}
const mutations = {
	PUSH_USER_HISTORY(state, data) {
		if (data.loginName.length > 21) {
			return
		}
		let index = state.userHistory.findIndex(item => item.loginName == data.loginName)
		if (index >= 0) {
			state.userHistory.splice(index, 1)
		}
		state.userHistory.push(data)
		if (state.userHistory.length > 5) {
			state.userHistory.shift()
		}

		state.userHistory = JSON.parse(JSON.stringify(state.userHistory))
	},
	UPDATE_USER_HISTORY_BY_INDEX(state, index, data) {
		state.userHistory[index] = Object.assign(state.userHistory[index], data)
		state.userHistory = JSON.parse(JSON.stringify(state.userHistory))
	},
}
const getters = {

	userHistory(state) {
		return state.userHistory
	},
}
const actions = {
	async login(store, data) {
		let tempData = Object.assign({}, data)
		if (data.loginType != 0 && data.loginType != 8) {
			data.password = check.passwordFilter(data.password)
		}
		let res = await api.post('player/login', data)
		if (check.ok(res)) {
			let temp =  Object.assign({},res[0].data.data)
			tempData = Object.assign(temp, tempData)
			store.commit('SET_USER_INFO', tempData, {
				root: true
			})
			res[0].data.data.loginType = data.loginType
			store.commit('PUSH_USER_HISTORY', tempData)
		}
		return res
	},
	async loginOut() {
		let res = await api.post('playerCenter/loginOut', {})
		return res
	},
	async loginAuto(store, data) {
		let res = await api.post('player/tokenLogin', data)
		if (check.ok(res)) {
			store.commit('SET_USER_INFO', res[0].data.data, {
				root: true
			})
		}
		return res
	},
	async getAgreement(store, data) {
		return await api.get('/h5/query/' + data, {
			clientId: 1
		})
	},

}

export default {
	namespaced: true,
	state,
	mutations,
	getters,
	actions
}
